'use strict';
// Independent AI-boundary checks. Synthetic values only; no network or credentials.
const test=require('node:test'),assert=require('node:assert/strict'),A=require('../app/src/main/assets/ai-contract.js');
test('AI image request allowlist accepts only supported mode/source pairs and returns frozen copies',()=>{for(const [mode,source]of [['budget','statement_image'],['food','food_image'],['food','food_camera']]){const original={version:1,mode,source,revision:7,clientAttempt:'test-attempt'},clean=A.validateRequest(original);assert.deepEqual(clean,original);assert.notEqual(clean,original);assert.ok(Object.isFrozen(clean));original.mode='execute';assert.equal(clean.mode,mode);assert.deepEqual(A.validateRequest(JSON.stringify(clean)),clean);}});
test('AI request rejects hidden state, identifiers, endpoints, execution and invalid integer/version fields',()=>{const good=A.request('budget','statement_image');for(const extra of [{history:[]},{profile:{}},{weights:[]},{apiKey:'synthetic-not-a-key'},{endpoint:'https://example.invalid'},{requestId:'forged'},{generation:1},{tools:[]},{execute:'anything'}])assert.throws(()=>A.validateRequest({...good,...extra}));for(const patch of [{version:2},{revision:-1},{revision:1.5},{revision:2147483648},{revision:'0'},{mode:'food'},{source:'food_camera'},{mode:'unknown'},{source:'execute_tool'}])assert.throws(()=>A.validateRequest({...good,...patch}));for(const input of [null,[],42,'{bad',Object.create({version:1})])assert.throws(()=>A.validateRequest(input));});
test('AI envelope byte bounds count multibyte characters and reject oversized input before parsing',()=>{for(const input of [' '.repeat(A.MAX_REQUEST_BYTES+1),'界'.repeat(Math.ceil(A.MAX_REQUEST_BYTES/3)+1)])assert.throws(()=>A.validateRequest(input));const event={version:1,event:'result',mode:'budget',source:'statement_image',requestId:'native-id',sessionId:'native-session',clientAttempt:'test-attempt',generation:1,revision:0,data:'界'.repeat(710000)};assert.throws(()=>A.validateEvent(event));});
const event=(kind,extra={})=>({version:1,event:kind,mode:'budget',source:'statement_image',requestId:'native-request-1',sessionId:'native-session',clientAttempt:'test-attempt',generation:1,revision:0,...extra});
test('AI terminal envelopes require bounded result or error fields without mixing outcomes',()=>{for(const valid of [event('started'),event('cancelled'),event('result',{data:'{"records":[]}'}),event('error',{error:'合成错误',errorCode:'parse'})])assert.ok(Object.isFrozen(A.validateEvent(valid)));for(const invalid of [event('result'),event('result',{data:''}),event('result',{data:{records:[]}}),event('result',{data:'{}',error:'mixed'}),event('error'),event('error',{error:'x'.repeat(501)}),event('error',{error:'failure',data:'{}'}),event('started',{data:'{}'}),event('cancelled',{error:'failure'}),event('execute',{data:'{}'}),event('started',{generation:0}),event('started',{requestId:'../bad'}),event('started',{requestId:'x'.repeat(81)}),event('started',{tools:[]})])assert.throws(()=>A.validateEvent(invalid));});
const S=require('../app/src/main/assets/ai-session.js');
const started=(request,id='request-one',generation=1)=>({...request,event:'started',requestId:id,sessionId:'native-session',generation});
const result=start=>({...start,event:'result',data:'{"records":[]}'});
test('AI attempt correlation rejects cancelled pending started event even when mode and revision are identical',()=>{const s=S.create(),a=A.request('budget','statement_image',0),b=A.request('budget','statement_image',0);assert.notEqual(a.clientAttempt,b.clientAttempt);assert.equal(s.begin(a),true);s.invalidate();assert.equal(s.begin(b),true);assert.equal(s.accept(started(a,'old',1)),false);assert.equal(s.current(),null);assert.equal(s.accept(started(b,'new',2)),true);assert.equal(s.accept(result(started(a,'old',1))),false);assert.equal(s.accept(result(started(b,'new',2))),true);assert.equal(s.status(),'ready');assert.equal(s.accept(result(started(b,'new',2))),false);});
test('AI identity gates reject mismatched session request generation revision mode source and attempt without losing owner',()=>{const s=S.create(),request=A.request('food','food_image',4),begin=started(request);assert.equal(s.begin(request),true);assert.equal(s.accept(begin),true);for(const patch of [{sessionId:'other-session'},{requestId:'other-request'},{generation:2},{revision:5},{mode:'budget',source:'statement_image'},{source:'food_camera'},{clientAttempt:'other-attempt'}]){assert.equal(s.accept({...result(begin),...patch}),false);assert.equal(s.current().requestId,begin.requestId);}assert.equal(s.accept(result(begin)),true);assert.equal(s.current(),null);});
test('AI repeated begin and replayed attempt are blocked and generations must increase within fixed session',()=>{const s=S.create(),a=A.request('budget','statement_image'),b=A.request('budget','statement_image');assert.equal(s.begin(a),true);assert.equal(s.begin(b),false);const first=started(a);assert.equal(s.accept(first),true);assert.equal(s.begin(b),false);assert.equal(s.accept({...first,event:'cancelled'}),true);assert.equal(s.begin(a),false);assert.equal(s.begin(b),true);assert.equal(s.accept(started(b,'next',1)),false);assert.equal(s.accept({...started(b,'next',2),sessionId:'foreign-session'}),false);assert.equal(s.accept(started(b,'next',2)),true);s.invalidate();assert.equal(s.accept(result(started(b,'next',2))),false);});
test('AI session destruction permanently rejects pending or active callbacks and new work',()=>{for(const active of [false,true]){const s=S.create(),request=A.request('food','food_image'),begin=started(request);assert.equal(s.begin(request),true);if(active)assert.equal(s.accept(begin),true);s.destroy();assert.equal(s.status(),'closed');assert.equal(s.current(),null);assert.equal(s.accept(begin),false);assert.equal(s.accept(result(begin)),false);assert.equal(s.accept({...begin,event:'error',error:'late',errorCode:'parse'}),false);assert.equal(s.begin(A.request('food','food_camera')),false);s.invalidate();assert.equal(s.begin(A.request('food','food_camera')),false);s.destroy();assert.equal(s.status(),'closed');}});
test('AI typed failures are allowlisted terminal events and never implicitly reserve retries',()=>{for(const code of ['auth','balance','rate','timeout','input','parse','cancelled','network','server']){const s=S.create(),request=A.request('budget','statement_image'),begin=started(request);s.begin(request);s.accept(begin);assert.equal(s.accept({...begin,event:'error',error:'合成恢复提示',errorCode:code}),true);assert.equal(s.status(),'error');assert.equal(s.current(),null);assert.equal(s.accept({...begin,event:'error',error:'合成恢复提示',errorCode:code}),false);}for(const code of ['',null,'execute','retry_automatically',42])assert.throws(()=>A.validateEvent(event('error',{error:'failure',errorCode:code})));assert.throws(()=>A.validateEvent(event('result',{data:'{}',errorCode:'parse'})));});
test('actual app native event route ignores stale and repeated results without ledger writes or draft overwrite',()=>{const fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom'),base=path.resolve(__dirname,'../app/src/main/assets');const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{url:'https://app.local/',runScripts:'outside-only'}),w=dom.window,calls=[],observers=[],Observer=w.MutationObserver;w.MutationObserver=class extends Observer{constructor(cb){super(cb);observers.push(this);}};w.scrollTo=()=>{};w.alert=()=>{};w.confirm=()=>true;w.setInterval=()=>0;w.Android={requestAi:raw=>calls.push(JSON.parse(raw)),notify:()=>{}};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};try{for(const script of w.document.querySelectorAll('script[src]'))w.eval(fs.readFileSync(path.join(base,script.getAttribute('src')),'utf8'));const $=id=>w.document.getElementById(id),send=value=>w.receiveAiEvent(JSON.stringify(value));$('recognize').click();$('recognize').click();assert.equal(calls.length,1);const first=started(calls[0],'first',1);send(first);send({...first,event:'cancelled'});$('recognize').click();assert.equal(calls.length,2);const second=started(calls[1],'second',2),draft=amount=>JSON.stringify({records:[{date:'10-08',type:'expense',category:'meals',amount,note:'合成测试',source:''}]});send({...first,event:'result',data:draft('11.00')});assert.equal($('review-dialog').open,false);send(second);send({...second,event:'result',data:draft('22.00')});assert.equal($('review-dialog').open,true);const amount=$('review-list').querySelector('[data-field=amount]');assert.equal(amount.value,'22.00');amount.value='55.00';send({...second,event:'result',data:draft('22.00')});assert.equal(amount.value,'55.00');$('close-review').click();$('recognize').click();const third=started(calls[2],'third',3);send(third);w.dispatchEvent(new w.Event('pagehide'));send({...third,event:'result',data:draft('99.00')});assert.equal($('review-dialog').open,false);$('recognize').click();assert.equal(calls.length,3);assert.equal(w.localStorage.getItem(w.BudgetModel.KEY),null);}finally{observers.forEach(observer=>observer.disconnect());w.close();}});

test('typed AI requests preserve exact approved text and reject hidden context mixed media and invalid Unicode',()=>{const text='  synthetic lunch 12.30\n"quoted" \\ end  ';for(const mode of ['budget','food']){const req=A.textRequest(mode,text,3,'typed-attempt');assert.equal(req.text,text);assert.equal(req.source,mode+'_text');assert.ok(Object.isFrozen(req));assert.deepEqual(A.validateRequest(JSON.stringify(req)),req);for(const extra of [{history:[]},{profile:{}},{date:'2026-01-01'},{image:'bytes'}])assert.throws(()=>A.validateRequest({...req,...extra}));}for(const invalid of ['', '  ', 'x'.repeat(4001),'\uD800','\uDC00',null])assert.throws(()=>A.validateText(invalid));assert.equal(A.validateText('界'.repeat(4000)).length,4000);assert.throws(()=>A.validateRequest({...A.request('food','food_image'),text:'hidden'}));});

test('actual text composer sends only exact typed input and result opens unsaved review',()=>{const fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom'),base=path.resolve(__dirname,'../app/src/main/assets');const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{url:'https://app.local/',runScripts:'outside-only'}),w=dom.window,calls=[],observers=[],Observer=w.MutationObserver;w.MutationObserver=class extends Observer{constructor(cb){super(cb);observers.push(this);}};w.scrollTo=()=>{};w.alert=()=>{};w.confirm=()=>true;w.setInterval=()=>0;w.Android={requestAi:raw=>calls.push(JSON.parse(raw)),notify:()=>{}};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};try{for(const script of w.document.querySelectorAll('script[src]'))w.eval(fs.readFileSync(path.join(base,script.getAttribute('src')),'utf8'));const $=id=>w.document.getElementById(id),text='  synthetic lunch 12.30\nexact input  ';$('ai-text-budget').click();assert.equal($('ai-compose-dialog').open,true);assert.equal($('ai-compose-text').value,'');$('ai-compose-text').value=text;$('ai-compose-text').dispatchEvent(new w.Event('input',{bubbles:true}));$('ai-compose-form').dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(calls.length,1);assert.equal(calls[0].text,text);assert.equal(calls[0].source,'budget_text');assert.deepEqual(Object.keys(calls[0]).sort(),['clientAttempt','mode','revision','source','text','version']);assert.equal($('ai-compose-dialog').open,false);const native={...calls[0],event:'started',sessionId:'native-session',requestId:'text-one',generation:1};delete native.text;w.receiveAiEvent(JSON.stringify(native));w.receiveAiEvent(JSON.stringify({...native,event:'result',data:JSON.stringify({records:[{date:'10-08',type:'expense',category:'meals',amount:'12.30',note:'synthetic',source:''}]})}));assert.equal($('review-dialog').open,true);assert.equal(w.localStorage.getItem(w.BudgetModel.KEY),null);}finally{observers.forEach(observer=>observer.disconnect());w.close();}});

test('typed revision invalidation targets the exact pending or active attempt',()=>{for(const active of [false,true]){const session=S.create(),request=A.textRequest('budget','synthetic',2,'edit-attempt');session.begin(request);const start={...started(request)};delete start.text;if(active)session.accept(start);assert.equal(session.owner().clientAttempt,request.clientAttempt);assert.equal(session.invalidateAttempt('unrelated'),false);assert.ok(session.owner());assert.equal(session.invalidateAttempt(request.clientAttempt),true);assert.equal(session.owner(),null);assert.equal(session.accept(start),false);assert.equal(session.accept({...start,event:'result',data:'{}'}),false);}});
test('actual composer edits cancel pending consent and stale results cannot revive review',()=>{const fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom'),base=path.resolve(__dirname,'../app/src/main/assets');const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{url:'https://app.local/',runScripts:'outside-only'}),w=dom.window,calls=[],observers=[],Observer=w.MutationObserver;w.MutationObserver=class extends Observer{constructor(cb){super(cb);observers.push(this);}};w.scrollTo=()=>{};w.alert=()=>{};w.confirm=()=>true;w.setInterval=()=>0;w.Android={requestAi:raw=>calls.push(JSON.parse(raw)),notify:()=>{}};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};try{for(const script of w.document.querySelectorAll('script[src]'))w.eval(fs.readFileSync(path.join(base,script.getAttribute('src')),'utf8'));const $=id=>w.document.getElementById(id),cancelled=[];w.Android.cancelAi=attempt=>cancelled.push(attempt);$('ai-text-budget').click();$('ai-compose-text').value='first exact draft';$('ai-compose-text').dispatchEvent(new w.Event('input'));$('ai-compose-form').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.equal(calls.length,1);$('ai-compose-form').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.equal(calls.length,1);$('ai-text-budget').click();$('ai-compose-text').dispatchEvent(new w.Event('input'));assert.equal(cancelled.length,0);$('ai-compose-text').value='revised draft';$('ai-compose-text').dispatchEvent(new w.Event('input'));assert.deepEqual(cancelled,[calls[0].clientAttempt]);const stale={...calls[0],event:'started',sessionId:'native-session',requestId:'old-text',generation:1};delete stale.text;w.receiveAiEvent(JSON.stringify(stale));w.receiveAiEvent(JSON.stringify({...stale,event:'result',data:JSON.stringify({records:[{date:'10-08',type:'expense',category:'meals',amount:'1.00'}]})}));assert.equal($('review-dialog').open,false);$('ai-compose-form').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.equal(calls.length,2);assert.equal(calls[1].text,'revised draft');assert.ok(calls[1].revision>calls[0].revision);$('ai-text-food').click();assert.equal($('ai-compose-text').value,'');assert.equal(cancelled.length,2);assert.equal(w.localStorage.getItem(w.BudgetModel.KEY),null);}finally{observers.forEach(observer=>observer.disconnect());w.close();}});

