test('date provenance preserves yearless evidence and manual pinning through unrelated edits',()=>{const normalized={date:'2026-10-08',inferredDateSource:'10-08',type:'expense',category:'meals',amount:'1',currency:'CNY'},draft=F.create([normalized],[{...normalized,date:'10-08',rawDate:'10-08'}],2026);assert.match(draft.rows[0].dateInfo.description,/2026/);assert.equal(draft.rows[0].dateInfo.rawDate,'10-08');let next=F.edit(draft,0,'amount','2');assert.equal(next.rows[0].dateInfo.rawDate,'10-08');assert.equal(next.rows[0].dateInfo.inferredSource,'10-08');next=F.edit(next,0,'date','2026-10-08');assert.equal(next.rows[0].dateInfo.pinned,true);assert.match(next.rows[0].dateInfo.description,/手动固定/);next=F.edit(next,0,'date','');assert.equal(next.rows[0].dateInfo.valid,false);assert.match(next.rows[0].dateInfo.description,/清空/);assert.equal(F.dateEvidence('2024-02-29','2024-02-29','',false,2026).valid,true);assert.equal(F.dateEvidence('02-29','2026-02-29','02-29',false,2026).valid,false);assert.throws(()=>F.dateEvidence('','','',false,2200));});
