test('financial type effects keep income refund transfers and repayments distinct in integer cents',()=>{for(const [type,expense,income,net]of [['expense',1230,0,-1230],['income',0,1230,1230],['refund',-1230,0,1230],['transfer',0,0,0],['repayment',0,0,0]]){const effect=F.typeEffect(type,1230);assert.equal(effect.expenseCents,expense);assert.equal(effect.incomeCents,income);assert.equal(effect.netCents,net);assert.ok(Object.isFrozen(effect));}assert.equal(F.typeEffect('unknown',100).valid,false);assert.equal(F.typeEffect('expense').expenseCents,null);assert.equal(F.typeEffect('refund').expenseCents,null);for(const invalid of [0,-1,1.5,NaN,Infinity,10000000001])assert.throws(()=>F.typeEffect('expense',invalid));const mixed=['expense','income','refund','transfer','repayment'].map(type=>F.typeEffect(type,100));assert.equal(mixed.reduce((sum,x)=>sum+x.expenseCents,0),0);assert.equal(mixed.reduce((sum,x)=>sum+x.incomeCents,0),100);});
