test('financial save summary uses exact mixed-type totals and blocks selected invalid rows only',()=>{const categories={expense:'meals',income:'工资',refund:'meals',transfer:'转账',repayment:'信用卡还款'},rows=Object.keys(categories).map(type=>({date:'2026-10-08',type,category:categories[type],amount:'10',currency:'CNY'}));rows.push({...rows[0],amount:'bad'});const draft=F.create(rows);const valid=F.saveSummary(draft,[true,true,true,true,true,false]);assert.equal(valid.valid,true);assert.equal(valid.count,5);assert.equal(valid.expenseCents,0);assert.equal(valid.incomeCents,1000);assert.equal(valid.netCents,1000);assert.equal(valid.types.refund.amountCents,1000);assert.ok(Object.isFrozen(valid.types.expense));const invalid=F.saveSummary(draft,[true,false,false,false,false,true]);assert.equal(invalid.valid,false);assert.deepEqual(invalid.invalidIndexes,[5]);assert.equal(invalid.netCents,null);assert.equal(F.saveSummary(draft,rows.map(()=>false)).valid,false);assert.throws(()=>F.saveSummary(draft,[true]));});
test('actual financial confirmation rejects intervening draft mutation before an atomic save',()=>{const fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom'),base=path.resolve(__dirname,'../app/src/main/assets');const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{url:'https://app.local/',runScripts:'outside-only'}),w=dom.window,calls=[],observers=[],Observer=w.MutationObserver;w.MutationObserver=class extends Observer{constructor(cb){super(cb);observers.push(this);}};w.scrollTo=()=>{};w.alert=()=>{};w.confirm=()=>true;w.setInterval=()=>0;w.Android={requestAi:raw=>calls.push(JSON.parse(raw)),notify:()=>{}};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};try{for(const script of w.document.querySelectorAll('script[src]'))w.eval(fs.readFileSync(path.join(base,script.getAttribute('src')),'utf8'));const $=id=>w.document.getElementById(id);w.receiveRecognition(JSON.stringify({records:[{date:'2026-10-08',type:'expense',category:'meals',amount:'12.30',note:'synthetic'}]}));let confirmation='';w.confirm=message=>{confirmation=message;const amount=$('review-list').querySelector('[data-field=amount]');amount.value='24.60';amount.dispatchEvent(new w.Event('input',{bubbles:true}));return true;};$('commit-review').click();assert.match(confirmation,/12.30/);assert.equal(w.localStorage.getItem(w.BudgetModel.KEY),null);assert.equal($('review-dialog').open,true);w.confirm=()=>true;$('commit-review').click();assert.equal(JSON.parse(w.localStorage.getItem(w.BudgetModel.KEY)).expenses[0].amount,2460);}finally{observers.forEach(observer=>observer.disconnect());w.close();}});

test('import guard tokens reject reentrant stale forged and repeated saves but allow deliberate retry after cancel',()=>{const guard=F.createImportGuard(),first=guard.issue();assert.equal(guard.claim({id:first.id}),false);assert.equal(guard.claim(first),true);assert.equal(guard.claim(first),false);assert.equal(guard.isClaimed(first),true);assert.equal(guard.finish(first,false),true);assert.equal(guard.claim(first),true);assert.equal(guard.finish(first,true),true);assert.equal(guard.claim(first),false);const second=guard.issue(),third=guard.issue();assert.equal(guard.claim(second),false);assert.equal(guard.claim(third),true);guard.invalidate();assert.equal(guard.isClaimed(third),false);assert.equal(guard.finish(third,true),false);});
