const WB=require('../app/src/main/assets/ai-write-boundary.js');test('AI append capability cannot change profile settings health collections or existing history',()=>{const before={version:5,settings:{budget:123},expenses:[{id:'old',amount:100}],nutrition:[],weights:[{id:'weight',kg:60}],favorites:[],profile:{age:30},exercises:[],completedFoodDays:[]},clone=()=>JSON.parse(JSON.stringify(before)),next=clone();next.expenses.push({id:'new',date:'2026-10-08',type:'expense',category:'meals',amount:200,note:'',source:''});assert.equal(WB.assertAppend(before,next,'budget',1),next);for(const key of ['settings','nutrition','weights','favorites','profile','exercises','completedFoodDays']){const bad=JSON.parse(JSON.stringify(next));bad[key]=Array.isArray(bad[key])?[...bad[key],{id:'injected'}]:{injected:true};assert.throws(()=>WB.assertAppend(before,bad,'budget',1));}const changed=JSON.parse(JSON.stringify(next));changed.expenses[0].amount=999;assert.throws(()=>WB.assertAppend(before,changed,'budget',1));const duplicate=JSON.parse(JSON.stringify(next));duplicate.expenses[1].id='old';assert.throws(()=>WB.assertAppend(before,duplicate,'budget',1));assert.throws(()=>WB.assertAppend(before,next,'food',1));assert.throws(()=>WB.assertAppend(before,next,'budget',2));const food=clone();food.nutrition.push({id:'meal',date:'2026-10-08',name:'meal',grams:100,kcal:150,lowKcal:100,highKcal:200,note:''});assert.equal(WB.assertAppend(before,food,'food',1),food);for(const field of ['prompt','confidence','rawDate','requestId','image']){const bad=JSON.parse(JSON.stringify(food));bad.nutrition[0][field]='session-only';assert.throws(()=>WB.assertAppend(before,bad,'food',1));}});
