test('actual AI food errors associate invalid fields and focus repair while portion state is accessible',()=>{const fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom'),base=path.resolve(__dirname,'../app/src/main/assets');const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{url:'https://app.local/',runScripts:'outside-only'}),w=dom.window,calls=[],observers=[],Observer=w.MutationObserver;w.MutationObserver=class extends Observer{constructor(cb){super(cb);observers.push(this);}};w.scrollTo=()=>{};w.alert=()=>{};w.confirm=()=>true;w.setInterval=()=>0;w.Android={requestAi:raw=>calls.push(JSON.parse(raw)),notify:()=>{}};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};try{for(const script of w.document.querySelectorAll('script[src]'))w.eval(fs.readFileSync(path.join(base,script.getAttribute('src')),'utf8'));const $=id=>w.document.getElementById(id);w.receiveFoodRecognition(JSON.stringify({name:'meal',portionGrams:200,caloriesLow:100,caloriesHigh:300}),false);$('food-form').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.equal($('ai-food-form-error').hidden,false);assert.equal($('ai-food-form-error').getAttribute('role'),'alert');assert.equal(w.document.activeElement,$('ai-food-manual'));$('ai-food-half').click();assert.equal($('ai-food-half').getAttribute('aria-pressed'),'true');$('food-grams').value='0';$('food-grams').dispatchEvent(new w.Event('input'));$('food-form').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.equal(w.document.activeElement,$('food-grams'));assert.equal($('food-grams').getAttribute('aria-invalid'),'true');assert.equal($('food-grams').getAttribute('aria-errormessage'),'ai-food-form-error');assert.equal(w.localStorage.getItem(w.BudgetModel.KEY),null);}finally{observers.forEach(observer=>observer.disconnect());w.close();}});
