test('actual AI reset scrubs raw session buffers preserves storage and rejects old callbacks before fresh use',()=>{const fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom'),base=path.resolve(__dirname,'../app/src/main/assets');const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{url:'https://app.local/',runScripts:'outside-only'}),w=dom.window,calls=[],observers=[],Observer=w.MutationObserver;w.MutationObserver=class extends Observer{constructor(cb){super(cb);observers.push(this);}};w.scrollTo=()=>{};w.alert=()=>{};w.confirm=()=>true;w.setInterval=()=>0;w.Android={requestAi:raw=>calls.push(JSON.parse(raw)),notify:()=>{}};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};try{for(const script of w.document.querySelectorAll('script[src]'))w.eval(fs.readFileSync(path.join(base,script.getAttribute('src')),'utf8'));const $=id=>w.document.getElementById(id);let resets=0;w.Android.clearAiSession=()=>resets++;$('ai-text-budget').click();$('ai-compose-text').value='raw private synthetic text';$('ai-compose-text').dispatchEvent(new w.Event('input'));$('ai-compose-form').dispatchEvent(new w.Event('submit',{cancelable:true}));const before=w.localStorage.getItem(w.BudgetModel.KEY),old=started(calls[0]);delete old.text;w.document.querySelector('[data-ai-reset]').click();assert.equal(resets,1);assert.equal($('ai-compose-text').value,'');assert.equal($('review-list').children.length,0);assert.equal(w.localStorage.getItem(w.BudgetModel.KEY),before);w.receiveAiEvent(JSON.stringify(old));w.receiveAiEvent(JSON.stringify({...old,event:'result',data:JSON.stringify({records:[{date:'2026-10-08',type:'expense',category:'meals',amount:'1',currency:'CNY'}]})}));assert.equal($('review-dialog').open,false);$('ai-text-budget').click();assert.equal($('ai-compose-text').value,'');$('ai-compose-text').value='new session input';$('ai-compose-text').dispatchEvent(new w.Event('input'));$('ai-compose-form').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.equal(calls.length,2);assert.notEqual(calls[0].clientAttempt,calls[1].clientAttempt);w.dispatchEvent(new w.Event('pagehide'));assert.equal($('ai-compose-text').value,'');assert.equal(resets,2);}finally{observers.forEach(observer=>observer.disconnect());w.close();}});

test('strict AI response adapters reject unexpected actions getters and bidi control spoofing',()=>{const good={records:[{date:'2026-10-08',type:'expense',category:'meals',amount:'1',currency:'CNY',note:'<img src=https://example.invalid/x>'}]};assert.equal(F.parse(good).records[0].note,good.records[0].note);for(const patch of [{tools:[]},{profile:{}},{execute:'x'}])assert.throws(()=>F.parse({...good,...patch}));let read=false;const getter={};Object.defineProperty(getter,'records',{get(){read=true;return [];},enumerable:true});assert.throws(()=>F.parse(getter));assert.equal(read,false);const array=[];Object.defineProperty(array,0,{get(){read=true;return {};},enumerable:true});assert.throws(()=>F.parse({records:array}));assert.equal(read,false);for(const bad of ['a\u202Eb','a\u2066b','a\u0000b']){assert.throws(()=>F.parse({records:[{note:bad}]}));assert.throws(()=>FD.normalize({name:bad}));}assert.throws(()=>FD.normalize(Object.assign(Object.create({}),{name:'meal'})));});
test('actual untrusted response text stays literal and malformed replacement preserves the draft',()=>{const fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom'),base=path.resolve(__dirname,'../app/src/main/assets');const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{url:'https://app.local/',runScripts:'outside-only'}),w=dom.window,calls=[],observers=[],Observer=w.MutationObserver;w.MutationObserver=class extends Observer{constructor(cb){super(cb);observers.push(this);}};w.scrollTo=()=>{};w.alert=()=>{};w.confirm=()=>true;w.setInterval=()=>0;w.Android={requestAi:raw=>calls.push(JSON.parse(raw)),notify:()=>{}};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};try{for(const script of w.document.querySelectorAll('script[src]'))w.eval(fs.readFileSync(path.join(base,script.getAttribute('src')),'utf8'));const $=id=>w.document.getElementById(id),literal='<img src="https://example.invalid/x" onerror="window.injected=1">';w.receiveRecognition(JSON.stringify({records:[{date:'2026-10-08',type:'expense',category:'meals',amount:'1',currency:'CNY',note:literal}]}),false);assert.equal($('review-list').querySelector('[data-field=note]').value,literal);assert.equal($('review-list').querySelector('img,a,script'),null);assert.equal(w.injected,undefined);w.receiveRecognition(JSON.stringify({records:[{amount:'2',execute:'fetch'}]}),false);assert.equal($('review-list').querySelector('[data-field=note]').value,literal);assert.equal(calls.length,0);assert.equal(w.localStorage.getItem(w.BudgetModel.KEY),null);}finally{observers.forEach(observer=>observer.disconnect());w.close();}});

test('pending cancellation can terminate before started and closed session never becomes cancelled',()=>{const session=S.create(),req=A.request('budget','statement_image');session.begin(req);assert.equal(session.accept({...started(req),event:'cancelled'}),true);assert.equal(session.owner(),null);assert.equal(session.accept(started(req)),false);session.destroy();session.invalidate();assert.equal(session.status(),'closed');});
test('actual native delivery claim rejects revoked queued results without cancelling a newer attempt',()=>{const fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom'),base=path.resolve(__dirname,'../app/src/main/assets');const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{url:'https://app.local/',runScripts:'outside-only'}),w=dom.window,calls=[],observers=[],Observer=w.MutationObserver;w.MutationObserver=class extends Observer{constructor(cb){super(cb);observers.push(this);}};w.scrollTo=()=>{};w.alert=()=>{};w.confirm=()=>true;w.setInterval=()=>0;w.Android={requestAi:raw=>calls.push(JSON.parse(raw)),notify:()=>{}};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};try{for(const script of w.document.querySelectorAll('script[src]'))w.eval(fs.readFileSync(path.join(base,script.getAttribute('src')),'utf8'));const $=id=>w.document.getElementById(id),cancelled=[];let allow=true;w.Android.consumeAiEvent=()=>allow;w.Android.cancelAi=attempt=>cancelled.push(attempt);$('recognize').click();const first={...started(calls[0]),deliveryToken:'token-start'};w.receiveAiEvent(JSON.stringify(first));allow=false;w.receiveAiEvent(JSON.stringify({...first,event:'result',deliveryToken:'token-result',data:JSON.stringify({records:[{date:'2026-10-08',type:'expense',category:'meals',amount:'1',currency:'CNY'}]})}));assert.equal($('review-dialog').open,false);assert.deepEqual(cancelled,[calls[0].clientAttempt]);$('recognize').click();assert.equal(calls.length,2);w.receiveAiEvent(JSON.stringify({...first,event:'result',data:'{}'}));assert.equal(cancelled.length,1);allow=true;const second={...started(calls[1],'second-request',2),deliveryToken:'token-second'};w.receiveAiEvent(JSON.stringify(second));w.receiveAiEvent(JSON.stringify({...second,event:'result',deliveryToken:'token-second-result',data:JSON.stringify({records:[{date:'2026-10-08',type:'expense',category:'meals',amount:'2',currency:'CNY'}]})}));assert.equal($('review-dialog').open,true);assert.equal($('review-list').querySelector('[data-field=amount]').value,'2');assert.equal(w.localStorage.getItem(w.BudgetModel.KEY),null);}finally{observers.forEach(observer=>observer.disconnect());w.close();}});

test('actual result waits behind a manual form without focus theft and opens only on one explicit View',()=>{const fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom'),base=path.resolve(__dirname,'../app/src/main/assets');const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{url:'https://app.local/',runScripts:'outside-only'}),w=dom.window,calls=[],observers=[],Observer=w.MutationObserver;w.MutationObserver=class extends Observer{constructor(cb){super(cb);observers.push(this);}};w.scrollTo=()=>{};w.alert=()=>{};w.confirm=()=>true;w.setInterval=()=>0;w.Android={requestAi:raw=>calls.push(JSON.parse(raw)),notify:()=>{}};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};try{for(const script of w.document.querySelectorAll('script[src]'))w.eval(fs.readFileSync(path.join(base,script.getAttribute('src')),'utf8'));const $=id=>w.document.getElementById(id);w.Android.consumeAiEvent=()=>true;let receipt=true;w.Android.isAiResultCurrent=()=>receipt;$('recognize').click();const begin={...started(calls[0]),deliveryToken:'token-start'};w.receiveAiEvent(JSON.stringify(begin));$('budget-quick-expense').click();$('amount').value='77.50';$('amount').focus();const focus=w.document.activeElement;w.receiveAiEvent(JSON.stringify({...begin,event:'result',deliveryToken:'token-result',data:JSON.stringify({records:[{date:'2026-10-08',type:'expense',category:'meals',amount:'2',currency:'CNY'}]})}));assert.equal(w.document.activeElement,focus);assert.equal($('amount').value,'77.50');assert.equal($('review-dialog').open,false);assert.equal($('ai-ready').hidden,false);$('ai-ready-view').click();assert.equal($('review-dialog').open,false);w.handleBack();$('ai-ready-view').click();assert.equal($('review-dialog').open,true);$('ai-ready-view').click();assert.equal($('review-list').children.length,1);assert.equal(w.localStorage.getItem(w.BudgetModel.KEY),null);}finally{observers.forEach(observer=>observer.disconnect());w.close();}});
