test('actual Today AI status and ready actions stay outside hidden routes through navigation and modal close',async()=>{const fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom'),base=path.resolve(__dirname,'../app/src/main/assets');const dom=new JSDOM(fs.readFileSync(path.join(base,'index.html'),'utf8'),{url:'https://app.local/',runScripts:'outside-only'}),w=dom.window,calls=[],observers=[],Observer=w.MutationObserver;w.MutationObserver=class extends Observer{constructor(cb){super(cb);observers.push(this);}};w.scrollTo=()=>{};w.alert=()=>{};w.confirm=()=>true;w.setInterval=()=>0;w.Android={requestAi:raw=>calls.push(JSON.parse(raw)),notify:()=>{}};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'));};try{for(const script of w.document.querySelectorAll('script[src]'))w.eval(fs.readFileSync(path.join(base,script.getAttribute('src')),'utf8'));const $=id=>w.document.getElementById(id),visible=id=>{assert.equal($(id).closest('[hidden]'),null);assert.equal($(id).closest('dialog:not([open])'),null);};$('mode-food').click();w.WellnessUI.route('today');$('wellness-quick-photo').click();assert.equal(calls.length,1);visible('ai-task-status');const begin=started(calls[0]);w.receiveAiEvent(JSON.stringify(begin));w.receiveAiEvent(JSON.stringify({...begin,event:'phase',phase:'sending'}));visible('ai-task-status');for(const route of ['log','progress','plan','today']){w.WellnessUI.route(route);visible('ai-task-status');}$('add-weight').click();const blocker=w.document.querySelector('dialog[open]');assert.ok(blocker);$('weight-kg').focus();const priorFocus=w.document.activeElement;await new Promise(resolve=>w.setTimeout(resolve,0));assert.equal($('ai-task-cancel').closest('dialog'),blocker);assert.equal(w.document.activeElement,priorFocus);const choice=w.document.createElement('select');choice.innerHTML='<option>A</option><option>B</option>';blocker.append(choice);w.SelectSheet.init();choice.nextElementSibling.click();await new Promise(resolve=>w.setTimeout(resolve,0));assert.equal(w.SelectSheet.isOpen(),true);assert.notEqual($('ai-task-cancel').closest('dialog').id,'select-sheet');w.handleBack();await new Promise(resolve=>w.setTimeout(resolve,0));assert.equal($('ai-task-cancel').closest('dialog'),blocker);w.receiveAiEvent(JSON.stringify({...begin,event:'result',data:JSON.stringify({name:'meal',portionGrams:200,caloriesLow:100,caloriesHigh:300})}));visible('ai-ready');w.handleBack();visible('ai-ready');visible('ai-task-status');assert.equal(w.WellnessUI.currentRoute,'today');assert.equal($('food-dialog').open,false);}finally{observers.forEach(observer=>observer.disconnect());w.close();}});
